class Shape:
    def area(self):
        raise NotImplementedError()

class Square(Shape):
    def area(self):
        return math.pow(self.length, 2)

class Circle(Shape):
    def area(self):
        return math.pi * math.pow(self.radius, 2)

class AreaCalculator:
    def calculate_total_area(self):
        return sum(shape.area() for shape in self.shapes)
